    when 'rare_unknown' then 'rarity ' || (p_detail->>'rare') || ': no such rarity'
    when 'rare_no_roll' then 'rarity ' || (p_detail->>'rare') || ', made by ' || coalesce(p_detail->>'fn', 'no door')
    when 'no_origin' then 'origin: ' || coalesce(p_detail->>'fn', 'none')
    else p_reason end
